// Generated by Contentrain Migrate. A hero's heading is sized to fit its column: the global
// stylesheet's hero rule takes the smallest of its role's size, the size that sets it in at
// most four lines and the size that keeps its longest word on one line. This gives that rule
// the heading's length, read when the site is built, so an edited heading is fitted again.

/** The heading's character count and its longest word's, as the hero rule's variables. */
export function headingFit(heading: string | undefined): string {
  const text = (heading ?? '').trim().replace(/\s+/g, ' ')
  const word = text.split(' ').reduce((n, w) => Math.max(n, w.length), 0)
  return `--cr-chars: ${Math.max(text.length, 1)}; --cr-word: ${Math.max(word, 1)}`
}
